&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Identification of immediate actions/escalation needed to mitigate risk to product, employee&amp;nbsp;safety,&amp;nbsp;or schedule as&amp;nbsp;appropriate.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Identify&amp;nbsp;any Continuous Improvements to the process/equipment and drive through to completion any projects to which may be assigned.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ensure high standards of housekeeping are adhered to at all times.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Participate in internal/regulatory audits as&amp;nbsp;required.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
