&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;2+ years’ experience preferably in pharmaceutical manufacturing or other regulated industry coop, and internship experience is considered.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with viral vectors and/or biological processes.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
