&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ability and desire to work in a fast-paced, start-up environment is essential.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
