&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;19&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;DevOps Toolchain Support: Assist&amp;nbsp;in the administration and maintenance of our core DevOps tools. Handle routine tasks such as managing user permissions, responding to&amp;nbsp;initial&amp;nbsp;alerts, and performing basic configuration changes based on established runbooks and procedures.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:714,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:240,&amp;quot;335559991&amp;quot;:357}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
